 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let index = 0;
+
+  while (index < template.length) {
+    const open = template.indexOf("{{", index);
+    if (open === -1) {
+      if (index < template.length) {
+        tokens.push({ kind: "text", text: template.slice(index) });
+      }
+      break;
+    }
+
+    if (open > index) {
+      tokens.push({ kind: "text", text: template.slice(index, open) });
+    }
+
+    const raw = template.startsWith("{{{", open);
+    const close = raw ? template.indexOf("}}}", open + 3) : template.indexOf("}}", open + 2);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+
+    const start = open + (raw ? 3 : 2);
+    const inner = template.slice(start, close).trim();
+
+    if (raw) {
+      tokens.push({ kind: "value", expr: inner, raw: true });
+      index = close + 3;
+      continue;
+    }
+
+    if (inner.startsWith("#if")) {
+      tokens.push({ kind: "if", path: inner.slice(3).trim() });
+    } else if (inner === "else") {
+      tokens.push({ kind: "else" });
+    } else if (inner === "/if") {
+      tokens.push({ kind: "end" });
+    } else {
+      tokens.push({ kind: "value", expr: inner, raw: false });
+    }
+
+    index = close + 2;
+  }
+
+  return tokens;
 }
